import React, { useState } from 'react';
import { useAuth } from '../../context/AuthContext';
import Sidebar from './Sidebar';
import Header from './Header';
import ShipmentsView from '../Shipments/ShipmentsView';
import UsersView from '../Users/UsersView';
import './Dashboard.css';

const Dashboard = () => {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [activeView, setActiveView] = useState('shipments');
  const { user } = useAuth();
  

  const toggleSidebar = () => {
    setSidebarOpen(!sidebarOpen);
  };

  return (
    <div className="dashboard-container">
      <Sidebar 
        isOpen={sidebarOpen} 
        onClose={() => setSidebarOpen(false)} 
        setActiveView={setActiveView}
        activeView={activeView}
      />
      <div className="dashboard-main">
        <Header onMenuClick={toggleSidebar} user={user} />
        <div className="dashboard-content">
          {activeView === 'shipments' && <ShipmentsView />}
          {activeView === 'users' && <UsersView />}
          {activeView === 'analytics' && (
            <div className="placeholder-view">
              <div className="coming-soon-icon">📊</div>
              <h2>Analytics Dashboard</h2>
              <p>This feature is coming soon!</p>
              <p className="coming-soon-desc">Analytics and reporting features will be available in a future update.</p>
            </div>
          )}
          {activeView === 'reports' && (
            <div className="placeholder-view">
              <div className="coming-soon-icon">📄</div>
              <h2>Reports</h2>
              <p>This feature is coming soon!</p>
              <p className="coming-soon-desc">Report generation and export features will be available in a future update.</p>
            </div>
          )}
          {activeView === 'settings' && (
            <div className="placeholder-view">
              <div className="coming-soon-icon">⚙️</div>
              <h2>Settings</h2>
              <p>This feature is coming soon!</p>
              <p className="coming-soon-desc">User preferences and system settings will be available in a future update.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
